DD.defineEntity('w8zap', {   // MoneyZap loan pad: stand on it and it bounces you high ("LOAN APPROVED")
  solid: true,
  spawn: t => ({ x: t.x, y: t.y + 10, w: 32, h: 6, cool: 0 }),
  update(e, G) {
    if (e.cool > 0) e.cool--;
    const p = G.pl;
    if (p.ground === e && p.onGround && e.cool === 0) {
      p.vy = -8.6; e.cool = 20; DD.SFX.boing(); DD.float(DD.cx(e), e.y - 4, 'LOAN APPROVED', '#7fe08a');
      if (G.s.forgivenLines === undefined) G.s.zapped = true;
    }
  },
  draw(e, ctx, G) {
    const X = DD.wx(e.x), Y = DD.wy(e.y);
    const pulse = 0.5 + 0.5 * Math.sin(G.frame / 12);
    ctx.save(); ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(X + 16, Y + 2, 2, X + 16, Y + 2, 30 + (e.cool ? 10 : 0)); g.addColorStop(0, 'rgba(90,255,150,' + (0.3 + 0.25 * pulse) + ')'); g.addColorStop(1, 'rgba(90,255,150,0)');
    ctx.fillStyle = g; ctx.fillRect(X - 20, Y - 30, 72, 60); ctx.restore();
    if (DD.ready('w8_mzpad')) ctx.drawImage(DD.IMG.w8_mzpad, e.cool > 8 ? 32 : 0, 0, 32, 12, X, Y - 2, 32, 12);
  },
});

DD.defineEntity('w8plate', {   // the board plate: stand on it and the brass gate rises
  solid: true,
  spawn: t => ({ x: t.x, y: t.y + 12, w: 32, h: 4, lit: 0 }),
  update(e, G) {
    if (e.lit > 0) e.lit--;
    const p = G.pl;
    if (!G.s.forgiven && p.ground === e && p.onGround) {
      G.s.forgiven = true; e.lit = 90;
      const g = DD.bodies.find(b => b.kind === 'w8gate'); if (g) g.open = true;
      DD.SFX.gate(); DD.banner('DEBT FORGIVENESS', 90, 'EMERGENCY BOARD MEETING'); DD.lines('forgiven');
    }
  },
  draw(e, ctx, G) {
    const X = DD.wx(e.x), Y = DD.wy(e.y), lit = G.s.forgiven || e.lit > 0;
    if (lit) {
      ctx.save(); ctx.globalCompositeOperation = 'lighter';
      const g = ctx.createRadialGradient(X + 16, Y, 2, X + 16, Y, 40); g.addColorStop(0, 'rgba(255,226,120,0.45)'); g.addColorStop(1, 'rgba(255,226,120,0)');
      ctx.fillStyle = g; ctx.fillRect(X - 30, Y - 40, 92, 60); ctx.restore();
    }
    if (DD.ready('w8_plate')) ctx.drawImage(DD.IMG.w8_plate, lit ? 32 : 0, 0, 32, 8, X, Y - 2, 32, 8);
  },
});

DD.defineEntity('w8gate', {   // brass boardroom gate: solid until the plate opens it, then it rises out of the way
  solid: e => !e.open,
  spawn: t => ({ x: t.x, y: t.y, w: 16, h: 112, y0: t.y, open: false }),
  update(e) { if (e.open && e.y > e.y0 - 112) e.y -= 2; },
  draw(e, ctx) {
    const X = DD.wx(e.x), Y = DD.wy(e.y);
    if (DD.ready('w8_gate')) ctx.drawImage(DD.IMG.w8_gate, X - 1, Y - 1);
    if (!e.open) { ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.fillStyle = 'rgba(255,214,110,0.10)'; ctx.fillRect(X - 6, Y, 28, e.h); ctx.restore(); }
  },
  stomp: () => false,
  touch: () => {},
});

DD.defineEntity('w8crv', {   // the Mobile VFA: a black CR-V covered in memorabilia, slides across the hole and carries Dot
  solid: true,
  spawn: t => ({ x: t.x, y: t.y + 9, w: 32, h: 14, x0: t.x, x1: t.x + 16 * 14, dir: 1, sp: 0.8, t: 0 }),
  update(e, G) {
    const p = G.pl, old = e.x;
    e.t++; e.x += e.dir * e.sp;
    if (e.x < e.x0) { e.x = e.x0; e.dir = 1; }
    if (e.x > e.x1) { e.x = e.x1; e.dir = -1; }
    if (p.ground === e && p.onGround) p.x += e.x - old;
    if (e.t % 14 === 0) DD.part && DD.part({ x: e.dir > 0 ? e.x - 10 : e.x + 42, y: e.y + 22, vx: -e.dir * 0.4, vy: -0.25, life: 36, max: 36, r: 2, col: 'rgba(200,196,184,0.7)', g: -0.005 });
  },
  draw(e, ctx, G) {
    const X = DD.wx(e.x), Y = DD.wy(e.y);
    ctx.save(); ctx.globalCompositeOperation = 'lighter';   // headlight pool on the way it drives
    const hx = e.dir > 0 ? X + 46 : X - 12, g = ctx.createRadialGradient(hx, Y + 17, 1, hx, Y + 17, 22); g.addColorStop(0, 'rgba(255,244,176,0.35)'); g.addColorStop(1, 'rgba(255,244,176,0)');
    ctx.fillStyle = g; ctx.fillRect(hx - 24, Y - 8, 48, 50); ctx.restore();
    if (DD.ready('w8_crv')) {   // the sprite faces right; mirror it when it drives left
      const bob = Math.round(Math.sin(e.t / 5)) * 0;
      ctx.save(); ctx.translate(X + 16, Y - 7 + bob); if (e.dir < 0) ctx.scale(-1, 1); ctx.drawImage(DD.IMG.w8_crv, -28, 0); ctx.restore();
    }
  },
});

DD.defineEntity('w8larue', {   // LaRue on his red-and-black mobility scooter: wakes when Dot is close, then chases; stomp him to bail him out
  spawn: t => ({ x: t.x, y: t.y, w: 18, h: 18, vx: 0, vy: 0, on: false, dir: -1, t: 0 }),
  update(e, G) {
    const p = G.pl;
    if (!e.on) { if (p.x > e.x - 16 * 10) { e.on = true; DD.float(DD.cx(e), e.y - 8, 'LARUE!', '#ff8a7a'); } else return; }
    const dir = DD.cx(p) < DD.cx(e) ? -1 : 1;
    e.vx = dir * 1.1; e.dir = dir; e.t++;
    DD.moveX(e, e.vx, false);
    e.vy = Math.min(e.vy + 0.4, 6); if (DD.moveY(e, e.vy, false)) e.vy = 0;
  },
  draw(e, ctx, G) {
    const n = (e.on && Math.floor(e.t / 6) % 2) ? 'w8_larue_b' : 'w8_larue_a';
    if (e.on && G.frame % 3 === 0) ctx.globalAlpha = 1;
    DD.spr(n, DD.wx(e.x + e.w / 2), DD.wy(e.y + e.h) + 1, e.dir > 0);
    if (!e.on) DD.text('ZZ', DD.wx(e.x) + 12, DD.wy(e.y) - 4 - (G.frame >> 4) % 3, '#cfd8ff', 1);
  },
  stomp(e, G, p) { if (!e.on) return false; e.dead = true; DD.addGot(2, DD.cx(e), e.y); DD.stars && DD.stars(DD.cx(e), e.y, 6, '#ffe680'); return true; },
  touch(e, G) { if (e.on && !e.dead) DD.hurt(DD.cx(e)); },
});

DD.defineEntity('w8laser', {   // a red laser dot the unseen group sweeps along the Ranch: hurts on touch, jump it
  spawn: t => ({ x: t.x, y: t.y + 12, w: 6, h: 6, x0: t.x, x1: t.x + 16 * 8, dir: 1 }),
  update(e) { e.x += e.dir * 1.4; if (e.x < e.x0 || e.x > e.x1) e.dir = -e.dir; },
  draw(e, ctx, G) {
    const X = DD.wx(e.x), Y = DD.wy(e.y);
    ctx.save(); ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = 'rgba(255,60,50,0.16)'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(X + 3 + 150, Y - 260); ctx.lineTo(X + 3, Y + 3); ctx.stroke();   // the beam from up on the ridge
    const g = ctx.createRadialGradient(X + 3, Y + 3, 0, X + 3, Y + 3, 12); g.addColorStop(0, 'rgba(255,70,60,0.8)'); g.addColorStop(1, 'rgba(255,70,60,0)');
    ctx.fillStyle = g; ctx.fillRect(X - 10, Y - 10, 26, 26); ctx.restore();
    ctx.fillStyle = '#ff3b3b'; ctx.fillRect(X, Y, 6, 6); ctx.fillStyle = '#ffd0d0'; ctx.fillRect(X + 2, Y + 2, 2, 2);
    ctx.fillStyle = '#9a1020'; ctx.fillRect(X, Y + 5, 6, 1); ctx.fillRect(X + 5, Y, 1, 6);
  },
  stomp: () => false,
  touch(e) { DD.hurt(DD.cx(e)); },
});

DD.defineEntity('w8secret', {   // a Dot secret: one per Dot, a sparkling star on a gold halo, touch to take it
  spawn: t => ({ x: t.x, y: t.y, w: 12, h: 12, t: 0 }),
  update(e) { e.t++; },
  draw(e, ctx) {
    const X = DD.wx(e.x), Y = DD.wy(e.y), k = 0.5 + 0.5 * Math.sin(e.t / 9);
    ctx.save(); ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(X + 6, Y + 6, 1, X + 6, Y + 6, 22); g.addColorStop(0, 'rgba(255,214,90,' + (0.35 + 0.25 * k) + ')'); g.addColorStop(1, 'rgba(255,214,90,0)');
    ctx.fillStyle = g; ctx.fillRect(X - 18, Y - 18, 48, 48); ctx.restore();
    ctx.fillStyle = Math.floor(e.t / 8) % 2 ? '#f0c84a' : '#fff2a6';
    ctx.fillRect(X + 5, Y, 2, 12); ctx.fillRect(X, Y + 5, 12, 2); ctx.fillRect(X + 3, Y + 3, 6, 6);
    ctx.fillStyle = '#fffbe0'; ctx.fillRect(X + 5, Y + 5, 2, 2);
  },
  stomp: () => false,
  touch(e, G) {
    if (e.dead) return;
    e.dead = true; G.s.secrets++; DD.addGot(10, DD.cx(e), e.y); DD.float(DD.cx(e), e.y, 'DOT SECRET!', '#f0c84a'); DD.SFX.vhs();
  },
});

